
import type { PromotionCombinesWithInput } from './PromotionCombinesWithInput.js';
import type { PromotionExclusivityInput } from './PromotionExclusivityInput.js';

export type PromotionCandidateInput = { /** Calculated discount amount for this promotion candidate before final application, when available. */ "amount_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Discount amount applied to the order for candidates in applied[]. */ "applied_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "combines_with"?: PromotionCombinesWithInput; /** Current money amount counted toward threshold_money for available[] candidates. */ "current_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "customer_facing_name": string; "discount_class"?: "order" | "line_item" | "service_charge"; "exclusivity"?: PromotionExclusivityInput; /** Additional money amount needed to reach threshold_money for available[] candidates. */ "gap_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "order_charge_ids"?: Array<string>; "order_line_item_ids"?: Array<string>; "promotion_code"?: string; "promotion_code_id"?: string; "promotion_decline_reason"?: "already_applied" | "automatic_disabled" | "buy_item_missing" | "code_invalid" | "code_required" | "codes_disabled" | "currency_mismatch" | "disabled" | "exhausted" | "expired" | "max_promotions_reached" | "minimum_not_met" | "no_discountable_balance" | "not_combinable" | "not_eligible" | "not_yet_started" | "superseded" | "superseded_by_better_offer" | "unknown_type"; "promotion_id": string; "stacking_mode"?: "continue" | "stop_after"; /** Minimum money amount required by a threshold rule for available[] candidates. */ "threshold_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Discount amount this candidate would have applied if it had been eligible and won conflict resolution. */ "would_have_applied_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; };
